import copy
from dataclasses import FrozenInstanceError, dataclass, field
from decimal import Decimal

def append_bad(item, bucket=[]):
    bucket.append(item)
    return bucket

assert append_bad("a") == ["a"] and append_bad("b") == ["a", "b"]   # shared default

@dataclass(frozen=True)
class Key:
    customer_id: int
    ds: str
    tags: list[str] = field(default_factory=list, compare=False, hash=False)

key = Key(1, "2026-10-04")
assert {key: "row"}[Key(1, "2026-10-04")] == "row"   # equal and hashable
try:
    key.ds = "2026-10-05"
except FrozenInstanceError:
    pass
else:
    raise AssertionError("expected FrozenInstanceError")
key.tags.append("vip")                               # frozen is shallow
assert key.tags == ["vip"] and Key(2, "x").tags == []

