import functools

def wrapped_without(fn):
    def wrapper(*args):
        return fn(*args)
    return wrapper

def wrapped_with(fn):
    @functools.wraps(fn)
    def wrapper(*args):
        return fn(*args)
    return wrapper

def load():
    return "rows"

assert wrapped_without(load).__name__ == "wrapper"
assert wrapped_with(load).__name__ == "load" and wrapped_with(load).__wrapped__ is load

class Account:
    def __init__(self, owner, balance=0):
        self.owner, self.balance = owner, balance

    @classmethod
    def from_amounts(cls, owner, amounts):
        return cls(owner, sum(amounts))

class SavingsAccount(Account):
    pass

assert type(SavingsAccount.from_amounts("ana", [1, 2])) is SavingsAccount

